const chain=[
 [SOURCE.originalProof,'a43054848a1d6f915471dc8625a56e4406243887'],
 ['255322bd1f430696fb1a21d81653a58bf1ac129a','d793f71c69ec07eba061fb0b2b4b975f18dd9e38'],
 ['4986a685c256e1966b97f9538e754a46e4246d47','effe9c1152f534b6f746713de59083e6c17a5035'],
 [SOURCE.runtime,'75d392586953d990cf346c7b82f69f7ef246b133'],
];
function gitCommand(change=()=>{}){return async(program,args)=>{
 assert.equal(program,'git');assert.deepEqual(args.slice(0,2),['-C','fixture']);const command=args[2];
 let stdout;
 if(command==='rev-list'){const index=chain.findIndex(([revision])=>revision===args.at(-1));assert.ok(index>=0&&index<3);stdout=`${chain[index][0]} ${chain[index+1][0]}`;}
 else if(command==='rev-parse'){const row=chain.find(([revision])=>args[3]===revision+'^{tree}');assert.ok(row);stdout=row[1];}
 else{assert.equal(command,'diff-tree');assert.deepEqual(args.slice(-2),[SOURCE.runtime,SOURCE.originalProof]);stdout=reviewedDelta;}
 return {stdout:change(command,stdout,args)??stdout};
};}
test('only exact reviewed C3 chain maps component production applicability, never other proof guards',async()=>{
 const revisions={proofRevision:SOURCE.originalProof,runtimeRevision:SOURCE.runtime};
 const result=await residencyComponentSourceApplicability('fixture',revisions,gitCommand());
 assert.equal(result.directParent,false);assert.deepEqual(result.reviewedAncestry,chain.map(([revision])=>revision));assert.match(result.reviewedExactDeltaSha256,/^[a-f0-9]{64}$/);assert.ok(result.exclusions.includes('whole-tree equivalence'));
 for(const [command,change] of [['rev-list',s=>s+' '+SOURCE.runtime],['rev-parse',s=>'f'.repeat(40)],['diff-tree',s=>s.replace('f4d3b99','e4d3b99')],['diff-tree',s=>s+'\n:unexpected production path']])await assert.rejects(residencyComponentSourceApplicability('fixture',revisions,gitCommand((c,s)=>c===command?change(s):s)));
 for(const [revision] of chain.slice(1,3)){
  await assert.rejects(residencyComponentSourceApplicability('fixture',revisions,gitCommand((command,value,args)=>command==='rev-list'&&args.at(-1)===revision?value.replace(SOURCE.runtime,'f'.repeat(40)).replace('4986a685','f986a685'):value)));
  await assert.rejects(residencyComponentSourceApplicability('fixture',revisions,gitCommand((command,value,args)=>command==='rev-parse'&&args[3]===revision+'^{tree}'?'f'.repeat(40):value)));
 }
 await assert.rejects(residencyComponentSourceApplicability('fixture',{...revisions,proofRevision:'f'.repeat(40)},gitCommand()));
 await assert.rejects(residencyComponentSourceApplicability('fixture',{...revisions,runtimeRevision:SOURCE.proof},gitCommand()));
});

